sys_ux_client_script.required_translations:
[
    {
        "message": "A configuration error has occurred. Contact your system administrator."
    },
    {
        "message": "No recommendations are available."
    },
    {
        "message": "An error occurred while retrieving similar risk events. Contact the system administrator."
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const output = api.data.get_similar_risk_events.output;
    if (output && output.exception) {
        if (output.exception.issueType == "unconfigured")
            return helpers.translateSync("A configuration error has occurred. Contact your system administrator.");
        else if (output.exception.issueType == "no-data")
            return helpers.translateSync("No recommendations are available.");
        else if (output.exception.issueType == "error")
            return helpers.translateSync("An error occurred while retrieving similar risk events. Contact the system administrator.");
    }
}
